def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return value

    def normalize_phone(value):
        value = re.split(r"(?i)(?:ext|x|#)", value, maxsplit=1)[0]
        digits = re.sub(r"\D", "", value)

        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = value.strip()

        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value.strip(), fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized_rows = []

    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])

        # Drop rows without either a valid email or valid phone.
        if not email and not phone:
            continue

        source = row["source"].strip().lower()

        normalized_rows.append({
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": source,
            "manual": source.casefold() == "manual",
            "updated_dt": parse_updated(row["updated"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
        })

    count = len(normalized_rows)
    parent = list(range(count))
    rank = [0] * count

    def find(item):
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(left, right):
        left_root = find(left)
        right_root = find(right)

        if left_root == right_root:
            return

        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root

        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    # Union rows sharing a valid email or a valid phone plus last name.
    email_owner = {}
    phone_name_owner = {}

    for position, row in enumerate(normalized_rows):
        if row["email"]:
            previous = email_owner.get(row["email"])
            if previous is None:
                email_owner[row["email"]] = position
            else:
                union(position, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = phone_name_owner.get(key)
            if previous is None:
                phone_name_owner[key] = position
            else:
                union(position, previous)

    groups = {}
    for position, row in enumerate(normalized_rows):
        groups.setdefault(find(position), []).append(row)

    def pick_field(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        selected = max(
            candidates,
            key=lambda row: (
                row["manual"],
                row["updated_dt"],
                -row["index"],
            ),
        )
        return selected[field]

    output = []

    for group in sorted(
        groups.values(),
        key=lambda members: min(row["index"] for row in members),
    ):
        latest_updated = max(row["updated_dt"] for row in group)
        tags = set()

        for row in group:
            tags.update(row["tags"])

        output.append({
            "first_name": pick_field(group, "first_name"),
            "last_name": pick_field(group, "last_name"),
            "zip": pick_field(group, "zip"),
            "email": pick_field(group, "email"),
            "phone": pick_field(group, "phone"),
            "source": pick_field(group, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return output
